interface Logger { log(msg: string): void }
class ConsoleLogger implements Logger { log(msg: string){ console.log(msg) } }
class UserService {
  constructor(private logger: Logger) {}
  createUser(name: string){ this.logger.log(`create ${name}`) }
}
const logger = new ConsoleLogger()
const svc = new UserService(logger)

class ServiceLocator {
  private static instances: Map<string, any> = new Map()
  static get(name: string){ return this.instances.get(name) }
  static register(name: string, instance: any){ this.instances.set(name, instance) }
}
class OrderProcessor {
  process(order: any){ const logger = ServiceLocator.get('logger'); logger.log(order.id) }
}

// Version A
class PaymentServiceA {
  constructor(private processor: IPaymentProcessor) {}
  charge(amount:number){ this.processor.charge(amount) }
}

// Version B
class PaymentServiceB {
  charge(amount:number){
    const processor = GlobalRegistry.get('paymentProcessor')
    processor.charge(amount)
  }
}
